def solve_n3():
    solutions = []
    for x1 in range(1, 11):
        for x2 in range(1, 11):
            # Condition for x3: x1 + 1 must divide x2^2 + 1
            numerator = x2**2 + 1
            denominator = x1 + 1

            if numerator % denominator == 0:
                x3 = (numerator // denominator) - 1
                # x3 must be a positive integer
                if x3 >= 1:
                    solutions.append((x1, x2, x3))
    return solutions

n3_solutions = solve_n3()
print(f"Found {len(n3_solutions)} solutions for n=3.")
print("Solutions (x1, x2, x3):")
for sol in n3_solutions:
    print(sol)

